import React from 'react';
import 'primeicons/primeicons.css';

export default function ColorVariations() {
    const colors = ['primary', 'success', 'warning', 'danger', 'info', 'muted'];
    const sampleIcons = ['pi-home', 'pi-user']; // 5 icons only

    return (
        <div className='uls-grid gp10 col-4'>
            {colors.map((color) => (
                <div key={color} className='fxb column fvc gp4'>
                    <div className='text-sm'>{color}</div>
                    <div className='fxb gp4'>
                        {sampleIcons.map((icon) => (
                            <i key={`${color}-${icon}`} className={`uls-icons ${color} pi ${icon}`}></i>
                        ))}
                    </div>
                </div>
            ))}

            {/* Light background variations bound via --uls-icon-bg */}
            {['primary', 'success', 'warning', 'danger', 'info'].map((color) => (
                <div key={`bg-${color}`} className='fxb column fvc gp4'>
                    <div className='text-sm'>{`bg-${color}`}</div>
                    <div className='fxb gp4'>
                        {sampleIcons.map((icon) => (
                            <i key={`bg-${color}-${icon}`} className={`uls-icons s18 rounded bg-${color} pi ${icon}`}></i>
                        ))}
                    </div>
                </div>
            ))}
        </div>
    );
}